shader_type canvas_item;

uniform float flip : hint_range(0.0, 1.0) = 0.0;

void vertex() {
	float a = TAU * flip;
	vec3 x_arrow = vec3(cos(a), 0.0, -sin(a));
	vec3 y_arrow = vec3(0.0, 1.0, 0.0);
	vec3 z_arrow = vec3(sin(a), 0.0, cos(a));
	mat3 around_y = mat3(x_arrow, y_arrow, z_arrow);
	VERTEX = (around_y * vec3(VERTEX, 0.0)).xy;
}

shader_type canvas_item;

void fragment() {
	mat2 table = mat2(vec2(1.0, 2.0), vec2(3.0, 4.0));
	vec2 moved = table * vec2(5.0, 6.0);
	if (moved == vec2(23.0, 34.0)) {
		COLOR = vec4(0.37, 0.64, 0.57, 1.0);
	} else {
		COLOR = vec4(0.85, 0.2, 0.2, 1.0);
	}
}
